phase_profile.h.text:
#ifndef PRIVATE_FRAME_PHASE_PROFILE_H
#define PRIVATE_FRAME_PHASE_PROFILE_H

#include <stdint.h>

enum private_frame_phase {
    PRIVATE_PHASE_RETIRE,
    PRIVATE_PHASE_LIGHT,
    PRIVATE_PHASE_DISPLAY_UPDATE,
    PRIVATE_PHASE_WORLD_DRAW,
    PRIVATE_PHASE_HUD,
    PRIVATE_PHASE_COUNT
};

typedef struct private_frame_phase_row {
    int64_t ticks[PRIVATE_PHASE_COUNT];
    uint32_t calls[PRIVATE_PHASE_COUNT], valid[PRIVATE_PHASE_COUNT];
    uint32_t flags;
} private_frame_phase_row;

/* Fixed video-thread hooks. A NULL current row performs no clock query. */
void private_frame_phase_begin(unsigned int phase);
void private_frame_phase_end(unsigned int phase);

#endif

phase_observer.inc.text:
/* Private host observations only; no Source clocks, fields or GL calls. */
static private_frame_phase_row *private_phase_current;
static int64_t private_phase_start[PRIVATE_PHASE_COUNT];
static uint32_t private_phase_open;

void private_frame_phase_begin(unsigned int phase) {
    if (private_phase_current == NULL)
        return;
    if (phase >= PRIVATE_PHASE_COUNT) {
        private_phase_current->flags |= 1u;
        return;
    }
    const uint32_t bit = UINT32_C(1) << phase;
    if ((private_phase_open & bit) != 0)
        private_phase_current->flags |= 2u;
    ++private_phase_current->calls[phase];
    LARGE_INTEGER sample;
    if (!QueryPerformanceCounter(&sample) || sample.QuadPart < 0) {
        private_phase_current->flags |= 4u;
        private_phase_open &= ~bit;
        return;
    }
    private_phase_start[phase] = sample.QuadPart;
    private_phase_open |= bit;
}

void private_frame_phase_end(unsigned int phase) {
    if (private_phase_current == NULL)
        return;
    if (phase >= PRIVATE_PHASE_COUNT) {
        private_phase_current->flags |= 1u;
        return;
    }
    const uint32_t bit = UINT32_C(1) << phase;
    if ((private_phase_open & bit) == 0) {
        private_phase_current->flags |= 8u;
        return;
    }
    private_phase_open &= ~bit;
    LARGE_INTEGER sample;
    if (!QueryPerformanceCounter(&sample) || sample.QuadPart < private_phase_start[phase]) {
        private_phase_current->flags |= 4u;
        return;
    }
    const int64_t elapsed = sample.QuadPart - private_phase_start[phase];
    if (private_phase_current->ticks[phase] > INT64_MAX - elapsed) {
        private_phase_current->flags |= 16u;
        return;
    }
    private_phase_current->ticks[phase] += elapsed;
    ++private_phase_current->valid[phase];
}

static void private_phase_row_begin(private_frame_phase_row *row) {
    private_phase_current = row;
    private_phase_open = 0;
}

static void private_phase_row_end(void) {
    if (private_phase_current != NULL && private_phase_open != 0)
        private_phase_current->flags |= 32u;
    private_phase_current = NULL;
    private_phase_open = 0;
}

static void private_phase_print(uint64_t frame, const private_frame_phase_row *row) {
    printf("PERF_PHASE frame=%" PRIu64 " ticks=", frame);
    for (unsigned int phase = 0; phase < PRIVATE_PHASE_COUNT; ++phase)
        printf("%s%" PRId64, phase == 0 ? "" : ",", row->ticks[phase]);
    fputs(" calls=", stdout);
    for (unsigned int phase = 0; phase < PRIVATE_PHASE_COUNT; ++phase)
        printf("%s%" PRIu32, phase == 0 ? "" : ",", row->calls[phase]);
    fputs(" valid=", stdout);
    for (unsigned int phase = 0; phase < PRIVATE_PHASE_COUNT; ++phase)
        printf("%s%" PRIu32, phase == 0 ? "" : ",", row->valid[phase]);
    printf(" flags=%" PRIu32 "\n", row->flags);
}
